export function InAppNotification({
  message = '{{message}}',
  kind = '{{kind}}',
  accent = '{{accent}}',
  timestamp = '{{timestamp}}',
  dismissible = {{dismissible}},
}) {
  const icon = { info: 'i', success: '\u2713', warning: '!' }[kind] ?? 'i';
  return (
    <div role='status' style={{ display: 'flex', alignItems: 'flex-start', gap: 10, maxWidth: 400, padding: '12px 14px', background: '#FAF7F2', color: '#241430', borderLeft: `4px solid ${accent}`, borderRadius: 10, boxShadow: '0 6px 18px rgba(36,20,48,.12)', fontFamily: 'system-ui, sans-serif', fontSize: 14 }}>
      <span aria-hidden='true' style={{ width: 18, height: 18, borderRadius: '50%', background: accent, flexShrink: 0, marginTop: 2, display: 'grid', placeItems: 'center', color: '#FAF7F2', fontSize: 11, fontWeight: 700 }}>{icon}</span>
      <div style={{ flex: 1 }}>
        <p style={{ margin: '0 0 2px' }}>{message}</p>
        <time style={{ display: 'block', fontSize: 11, color: '#24143080' }} dateTime={timestamp}>{timestamp}</time>
      </div>
      {dismissible && (
        <button type='button' aria-label='Dismiss notification' style={{ border: 'none', background: 'transparent', fontSize: 16, cursor: 'pointer', padding: 0 }}>&times;</button>
      )}
    </div>
  );
}
